import runpy,unittest,sys,json,hashlib,pathlib
files=["tests/test_docker_build_context_contract.py","tests/test_docker_base_pins.py","tests/test_docker_packaging_tools.py","tests/test_docker_frontend_artifacts.py","tests/test_docker_browser_permissions.py","tests/test_release_constraints.py"]
suite=unittest.TestSuite()
for path in files:
 scope=runpy.run_path(path)
 for name,value in sorted(scope.items()):
  if name.startswith("test_") and callable(value): suite.addTest(unittest.FunctionTestCase(value))
result=unittest.TextTestRunner(verbosity=2).run(suite)
print(json.dumps({"source_sha256":{p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest() for p in [".dockerignore","Dockerfile","requirements.release.constraints.txt","requirements.txt",*files]}}))
sys.exit(not result.wasSuccessful())
